  ctx.strokeRect(backX - 10, backY - 8, 20, 16);

  // Operator cabin beside slewing ring
  ctx.fillStyle = '#f6f2e8';
  ctx.fillRect(topX + 4, topY - 4, 14, 12);
  ctx.fillStyle = '#3a6b84';
  ctx.fillRect(topX + 7, topY - 2, 9, 8);

